document.addEventListener('click', (event) => { if (!state.verseSelected || event.target.closest('[data-verse], #highlight-picker, .reader-aside')) return; state.verseSelected = false; state.highlightOpen = false; renderBible(); });
document.addEventListener('keydown', (event) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); $('#search-dialog').showModal(); $('#reference').focus(); } }); $('#reference').addEventListener('input', (event) => runSearch(event.target.value)); $('#book-picker-button').addEventListener('click', () => { renderBookResults(); $('#book-dialog').showModal(); $('#book-filter').focus(); }); $('#chapter-picker-button').addEventListener('click', () => { renderBookResults(); $('#book-dialog').showModal(); $('#book-filter').focus(); }); $('#book-filter').addEventListener('input', (event) => renderBookResults(event.target.value));
$('#translation-select').addEventListener('change', async (event) => { state.translation = event.target.value; await loadManifest(); await loadBook(); }); $('#previous-chapter').addEventListener('click', () => moveChapter(-1)); $('#next-chapter').addEventListener('click', () => moveChapter(1)); $('#font-plus').addEventListener('click', () => { state.fontSize = Math.min(28, state.fontSize + 1); $('#scripture').style.fontSize = `${state.fontSize}px`; }); $('#font-minus').addEventListener('click', () => { state.fontSize = Math.max(17, state.fontSize - 1); $('#scripture').style.fontSize = `${state.fontSize}px`; }); $('#complete-chapter').addEventListener('click', () => completeChapter()); $('#favorite-verse').addEventListener('click', toggleFavorite); $('#copy-verse').addEventListener('click', copyVerse); $('#start-camera').addEventListener('click', startCamera); $('#scan-demo').addEventListener('click', showScanResult); $('#image-upload').addEventListener('change', showScanResult); $('#open-scan-result').addEventListener('click', () => { stopCamera(); state.bookSlug = 'joao'; state.chapter = 3; state.selectedVerse = 16; openSection('biblia'); loadBook(); });
$('#open-favorites').addEventListener('click', () => { $('#search-dialog').showModal(); renderFavorites(); });
$('#open-daily-verse').addEventListener('click', (event) => { event.preventDefault(); if (!state.dailyVerse) return; state.bookSlug = state.dailyVerse.slug; state.chapter = state.dailyVerse.chapter; state.selectedVerse = state.dailyVerse.verse; openSection('biblia'); loadBook(); });
$('#reward-dialog button').addEventListener('click', advanceAfterReward); $('#reward-dialog').addEventListener('close', () => { advanceAfterReward(); if (!state.pendingActCompletion) return; const completedAct = state.pendingActCompletion; state.pendingActCompletion = null; renderActCompletion(completedAct); $('#act-completion-dialog').showModal(); });
window.addEventListener('resize', positionHighlightPicker);
Promise.resolve().then(loadManifest).then(loadBook).catch((error) => { $('#scripture').innerHTML = `<p class="loading">${error.message}</p>`; });
